def pre(p):
  p=p.split('00_Primary_Storage_Drive/',1)[-1]
  return next((x.split('/')[-1] for x in P if p.startswith(x)),p)
c=collections.defaultdict(lambda:[0,0])
for x in r: k=(x['status'],pre(x['path'])); c[k][0]+=1; c[k][1]+=int(x['size'])
for k,v in sorted(c.items()): print(k, v[0], f'{v[1]/1e9:.2f} GB')
def d(p,n): return '/'.join(p.split('00_Primary_Storage_Drive/',1)[-1].split('/')[:n])
print('--- review: loser dir -> survivor dir (top 15 by GB)')
c=collections.defaultdict(lambda:[0,0])
for x in r:
  if x['status']=='review': k=(d(x['path'],4),d(x['survivor_path'],4)); c[k][0]+=1; c[k][1]+=int(x['size'])
