import csv,glob,collections
txt=''.join(open(f,errors='ignore').read() for f in glob.glob('/Users/kristinarash/DEV/Flint/docs/**/*.md',recursive=True))
r=list(csv.DictReader(open('survivors_dry.csv')))
P='00_Primary_Storage_Drive/'
def tail(p): return '/'.join(p.split('/')[-2:])
def lab(p):
  p=p.split(P,1)[-1]
  for k in ['Videos/Eric Files','Strength and Conditioning Resources/Videos','From Landon Evans/Eric Files','Strength and Conditioning Resources','ERIC DOC/Seminar','drive-zotero-import']:
    if k in p: return k
  return '/'.join(p.split('/')[:2])
c=collections.defaultdict(lambda:[0,0])
for x in r: k=(lab(x['path']),lab(x['survivor_path'])); c[k][0]+=1; c[k][1]+=int(x['size'])
for k,v in sorted(c.items(),key=lambda z:-z[1][1]): print(f'{v[1]/1e9:6.2f} GB {v[0]:5d}  {k[0]}  ->kept in  {k[1]}')
bad=[x for x in r if 'drive-zotero-import' in x['path'] or 'drive-zotero-import' in x['survivor_path'] or x['id']==x['survivor_id']]
fl=[x for x in r if tail(x['path']) in txt or x['id'] in txt]
print('hands-off or self-survivor rows:',len(bad),' Flint-named losers:',len(fl))
"

